import {CHARTS} from './fireteam-data.js?v=36';
import * as E from './engine.js?v=36';
import * as S from './states.js?v=36';
import * as H from './hacking.js?v=36';
const norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'');
export const chart=u=>CHARTS[u.factionId]?.chart;
export const find=(s,u)=>(s.fireteams||[]).find(f=>!f.cancelled&&f.members.includes(u.id));
export const members=(s,f)=>f.members.map(id=>s.units.find(u=>u.id===id)).filter(Boolean);
export const coherent=(u,l)=>u.id===l.id||H.inZone(l,u);
export function forbidden(u,units=[]){return (!S.active(u)&&!u.pendingChoice)||u.offTable||u.deploymentPending||u.isDeployable||u.isDecoy||u.peripheral||u.ancillaryProfiles?.length&&units.some(v=>v.controllerId===u.id&&S.onTable(v))||u.infiltration||u.combatJump||u.parachutist||u.suppressive||['camouflaged','hiddenDeployment','impersonation2','holoecho','isolated','decoy','retreat','possessed'].some(k=>S.has(u,k));}
const rowMatch=(u,r)=>u.slug===r.slug&&(!/FTO/.test(r.name+' '+r.comment)||/\bFTO\b/.test(u.en));
export function assignment(u,table,data=chart(u)){return table?.units.find(r=>rowMatch(u,r))||data?.teams.find(t=>t.name==='Wildcards')?.units.find(r=>rowMatch(u,r));}
export function validate(s,ids,type,tableIndex,{coherency=true,leaderId=ids[0]}={}){const us=ids.map(id=>s.units.find(u=>u.id===id));if(us.some(u=>!u)||new Set(ids).size!==ids.length)return '无效或重复成员';const u=us[0];if(!u)return '请至少选择一名成员';const data=chart(u),table=data?.teams[tableIndex];if(!table?.type.includes(type))return '该军表不允许此类型的编组';if(type==='DUO'?ids.length!==2:type==='HARIS'?ids.length!==3:ids.length<3||ids.length>5)return '创建人数不符合 '+type;if(us.some(v=>v.team!==u.team||v.factionId!==u.factionId||(v.combatGroup||1)!==(u.combatGroup||1)))return '成员必须属于同一军队和战斗组';if(us.some(v=>forbidden(v,s.units)||find(s,v)))return '存在已组队、桌外、标记或其他不可入组成员';if((s.fireteams||[]).filter(f=>!f.cancelled&&f.team===u.team&&f.type===type).length>=(data.spec[type]||0))return '已达到 '+type+' 数量上限';const rows=us.map(v=>assignment(v,table,data));if(rows.some(r=>!r))return '单位或 FTO 配置不在此编组表';for(const r of [...table.units,...(data.teams.find(t=>t.name==='Wildcards')?.units||[])]){const n=rows.filter(x=>x===r).length;if(n<r.min||n>r.max)return '不符合 '+r.name+' 的最少/最多人数';}if(table.units.some(r=>r.required)&&!rows.some(r=>r.required))return '缺少至少一名星号必选成员';const leader=us.find(u=>u.id===leaderId);if(!leader)return '队长必须是成员';if(coherency&&us.some(v=>!coherent(v,leader)))return '成员须处于队长8″控制区内';return '';}
export function level(s,f){const counts={};for(const u of members(s,f)){const keys=[String(u.armyRef?.unitId||u.slug),norm(f.assignments?.[u.id]?.name)];for(const a of f.assignments?.[u.id]?.comment?.match(/\(([^)]+)\)/)?.[1]?.split(',')||[])keys.push(norm(a));for(const k of new Set(keys))counts[k]=(counts[k]||0)+1;}return Math.min(5,Math.max(1,...Object.values(counts)));}
export function sync(s){for(const team of [0,1]){const us=s.units.filter(u=>u.team===team&&u.armyRef&&!u.peripheral&&!u.isDeployable);if(us.some(u=>!u.factionId)){const matches=Object.entries(CHARTS).filter(([id,data])=>us.every(u=>data.configurations?.includes([u.armyRef.unitId,u.armyRef.groupId,u.armyRef.optionId].join('/'))));if(matches.length===1)for(const u of us)u.factionId=+matches[0][0];}}s.fireteams??=[];const events=[];for(const u of s.units)if(u.ftManaged){u.ftLevel=0;delete u.ftId;delete u.ftLeader;}for(const f of s.fireteams.filter(f=>!f.cancelled)){for(const u of members(s,f).filter(u=>forbidden(u,s.units)))events.push(...leave(s,u.id,'状态／装备不允许维持火力组'));if(f.cancelled)continue;const l=s.units.find(u=>u.id===f.leaderId);if(!l||!f.members.includes(l.id)){events.push(...cancel(s,f.id,'队长离组'));continue;}f.level=level(s,f);for(const u of members(s,f))Object.assign(u,{ftManaged:true,ftId:f.id,ftLevel:f.level,ftLeader:u.id===f.leaderId});}return events;}
export function cancel(s,id,reason='自愿解散'){const f=s.fireteams?.find(f=>f.id===id&&!f.cancelled);if(!f)return [];f.cancelled=true;for(const u of members(s,f)){u.ftManaged=true;u.ftLevel=0;delete u.ftId;delete u.ftLeader;delete u.ftReturn;}return [f.label+' 解散：'+reason];}
export function leave(s,id,reason='脱组'){const u=s.units.find(u=>u.id===id),f=u&&find(s,u);if(!f)return [];f.members=f.members.filter(x=>x!==id);u.ftReturn={id:f.id,epoch:(s.ftStatesEpoch||0)+1};u.ftManaged=true;u.ftLevel=0;delete u.ftId;delete u.ftLeader;const events=[u.name+' 脱组：'+reason];if((u.ftMasterFor||[]).some(key=>members(s,f).some(v=>norm(v.slug)===norm(key)||norm(v.en)===norm(key))))events.push(...cancel(s,f.id,'FT Master 指定单位的维持要求不再满足')); if(f.leaderId===id){const n=reason==='状态／装备不允许维持火力组'&&(!S.active(u)||S.has(u,'isolated'))?members(s,f).find(v=>v.number2&&!forbidden(v,s.units)):null;if(n)f.leaderId=n.id;else events.push(...cancel(s,f.id,'队长离组'));}if(!f.cancelled&&f.members.length<2)events.push(...cancel(s,f.id,'只剩一人'));if(!f.cancelled){f.level=level(s,f);for(const v of members(s,f))v.ftLevel=f.level;}return events;}
export function check(s,f,reason='一致性检查'){if(!f||f.cancelled)return [];const l=s.units.find(u=>u.id===f.leaderId),events=[];if(!l)return cancel(s,f.id,'队长不存在');for(const u of members(s,f))if(!coherent(u,l))events.push(...leave(s,u.id,reason+'：超出队长控制区'));return [...events,...sync(s)];}
export function create(s,proposal,{free=s.phase==='deploy'}={}){const {ids,type,tableIndex,leaderId=ids[0]}=proposal,error=validate(s,ids,type,tableIndex,{leaderId});if(error)throw Error(error);const us=ids.map(id=>s.units.find(u=>u.id===id)),team=us[0].team;if(!free){if(s.order||s.team!==team||s.phase!=='play')throw Error('局中创建仅限本方主动轮、命令之间');if(!(s.commandTokens?.[team]>0))throw Error('需要1枚指挥令');s.commandTokens[team]--;}
 const table=chart(us[0]).teams[tableIndex],f={id:'ft-'+(s.ftSerial=(s.ftSerial||0)+1),team,type,tableIndex,label:type+' / G'+(us[0].combatGroup||1),leaderId,members:[...ids],assignments:Object.fromEntries(us.map(u=>[u.id,assignment(u,table)]))};s.fireteams??=[];s.fireteams.push(f);for(const u of us){u.ftManaged=true;delete u.ftReturn;if(s.phase==='deploy')u.deploymentLocked=true;}sync(s);return f;}
export function proposals(s,team,{coherency=true}={}){const pool=s.units.filter(u=>u.team===team&&!forbidden(u,s.units)&&!find(s,u));if(!pool.length||!chart(pool[0]))return [];const data=chart(pool[0]),out=[];for(const [tableIndex,t] of data.teams.entries()){for(const type of t.type){const choices=pool.filter(u=>assignment(u,t,data));for(const n of type==='DUO'?[2]:type==='HARIS'?[3]:[5,4,3]){function visit(start,ids){if(ids.length===n){for(const l of ids){const e=validate(s,ids,type,tableIndex,{coherency,leaderId:l});if(!e){out.push({ids:[...ids],type,tableIndex,leaderId:l});break;}}return;}for(let i=start;i<choices.length;i++)visit(i+1,[...ids,choices[i].id]);}visit(0,[]);}}}return out;}
export function activate(s,u,source){let f=find(s,u),events=[];if(!f)return events;if(source==='regular'||source==='tactical'||source==='lieutenant'&&u.nco){f.leaderId=u.id;events.push(...check(s,f,'首技能移动前'));if(!f.cancelled&&find(s,u)){s.order.fireteamId=f.id;s.order.activatedIds=[...f.members];u.fireteamOrderMembers=[...f.members];}}else events.push(...leave(s,u.id,'使用个人命令独立激活'));return events;}
export const partners=(u,units)=>units.filter(v=>v.id!==u.id&&u.fireteamOrderMembers?.includes(v.id)&&S.active(v)&&S.onTable(v));
export function conclude(s){const events=[];for(const f of s.fireteams||[])events.push(...check(s,f,'命令结束一致性'));for(const u of s.units)delete u.fireteamOrderMembers;return events;}
export function statesPhase(s){s.ftStatesEpoch=(s.ftStatesEpoch||0)+1;for(const u of s.units){const r=u.ftReturn,f=s.fireteams?.find(f=>!f.cancelled&&f.id===r?.id);if(!f||r.epoch>s.ftStatesEpoch||forbidden(u,s.units)||find(s,u))continue;const l=s.units.find(n=>n.id===f.leaderId);if(coherent(u,l)){f.members.push(u.id);delete u.ftReturn;}}return sync(s);}
export function aroGroups(s,reactions,classify){return (s.fireteams||[]).filter(f=>!f.cancelled).map(f=>{const rows=members(s,f).map(u=>reactions[u.id]).filter(r=>r?.action&&!['none','delay'].includes(r.action)),counts={};for(const r of rows){const k=classify(r);counts[k]=(counts[k]||0)+1;}const majority=Object.keys(counts).find(k=>counts[k]>rows.length/2);return {f,rows,counts,majority};}).filter(g=>g.rows.length);}
export function resolveAROs(s,reactions,classify,choices={}){const events=[],groups=aroGroups(s,reactions,classify);for(const g of groups){const skill=g.majority||choices[g.f.id];if(!skill||!g.counts[skill])throw Error('请选择 '+g.f.label+' 的组 ARO 技能');}for(const g of groups){const skill=g.majority||choices[g.f.id];for(const r of g.rows)if(classify(r)!==skill)events.push(...leave(s,r.id,'ARO 与组技能 '+skill+' 不同'));}return [...events,...sync(s)];}

export function unavailableReason(u,units=[]){if(u.offTable||u.deploymentPending)return '尚未部署／桌外';if(u.peripheral||u.ancillaryProfiles?.length&&units.some(v=>v.controllerId===u.id&&S.onTable(v)))return '附属模型或其控制者不能入组';if(u.infiltration)return '具有渗透技能，不能入组';if(u.combatJump||u.parachutist)return '具有空降标签技能，不能入组';if(u.isDeployable||u.isDecoy)return '部署物／诱饵不能入组';if(!S.active(u)||S.has(u,'isolated'))return 'Null／孤立状态不能入组';if(forbidden(u,units))return '当前标记／压制／其他状态不允许入组';return '';}
export function preview(s,p){const reasons=[],us=p.ids.map(id=>s.units.find(u=>u.id===id)).filter(Boolean),team=us[0]?.team??p.team,affected=(s.fireteams||[]).filter(f=>!f.cancelled&&f.members.some(id=>p.ids.includes(id)));if(!p.ids.length)reasons.push('请勾选成员并指定队长');if(s.order)reasons.push('当前命令尚未结束，请在命令之间创建／重组');if(!['deploy','play'].includes(s.phase))reasons.push('仅部署阶段或游戏中可以创建');if(s.phase==='play'){if(s.team!==team)reasons.push('只能在本方主动轮创建／重组');if(!(s.commandTokens?.[team]>0))reasons.push('需要1枚指挥令，当前不足');}if(s.phase==='deploy'&&s.pregame){const pg=s.pregame,current=pg.stage==='deploy'?(pg.step%2===0?pg.firstDeployment:1-pg.firstDeployment):null;if(current!==team)reasons.push('当前不是该方的部署步骤');}for(const u of us){const r=unavailableReason(u,s.units);if(r)reasons.push(u.name+'：'+r);}const copy=structuredClone(s);for(const f of affected)cancel(copy,f.id,'重组预览');const error=validate(copy,p.ids,p.type,p.tableIndex,{leaderId:p.leaderId});if(error)reasons.push(error);const table=chart(us[0]||{})?.teams[p.tableIndex],assignments=Object.fromEntries(us.map(u=>[u.id,assignment(u,table)]));const n=us.length&&table?level(s,{members:p.ids,assignments}):0;return {reasons:[...new Set(reasons)],valid:!reasons.length,level:n,affected:affected.map(f=>({id:f.id,label:f.label})),cost:s.phase==='deploy'?0:1};}
export function reform(s,p){const result=preview(s,p);if(!result.valid)throw Error(result.reasons.join('；'));const next=structuredClone(s);for(const f of result.affected)cancel(next,f.id,'手动重组');const f=create(next,p);Object.assign(s,next);return f;}
